with fields as (select jsonb_agg(jsonb_build_object('key',key,'sectionKey','cardiovascular','label',label,'type','select','sequence',sequence,'required',false,'accessibilityLabel',label,'helpText','Legacy three-state Review of Systems value. Stored codes yes/no/na retain legacy YES/NO/N/A displays.','maxLength',null,'minimum',null,'maximum',null,'precision',null,'unit',null,'codeSystem',null,'options',jsonb_build_array(jsonb_build_object('code','yes','display','YES'),jsonb_build_object('code','no','display','NO'),jsonb_build_object('code','na','display','N/A')),'repeatMinimum',null,'repeatMaximum',null,'children','[]'::jsonb,'readOnly',false) order by sequence) value from (values ('chest_pain','Chest pain',10),('palpitation','Palpitations',20),('syncope','Syncope',30),('pnd','Paroxysmal nocturnal dyspnea',40),('doe','Dyspnea on exertion',50),('orthopnea','Orthopnea',60),('peripheal','Peripheral edema',70),('edema','Edema',80),('legpain_cramping','Leg pain or cramping',90),('history_murmur','History of murmur',100),('arrythmia','Arrhythmia',110),('heart_problem','Heart problem',120)) source(key,label,sequence)), schema as (select jsonb_build_object('stableKey','legacy.roscardiovascular','name','Review of Systems Cardiovascular','purpose','Legacy Review of Systems cardiovascular compatibility capture.','contextScope','encounter','owningService','clinical_operations','capability','encounters.auth_a','signaturePolicy','author-only','sections',jsonb_build_array(jsonb_build_object('key','cardiovascular','title','Cardiovascular','sequence',10,'description','Mapped from legacy form_ros cardiovascular fields.')),'fields',value,'rules','[]'::jsonb) schema_json from fields)
update clinical_form_definitions set effective_revision=1,updated_at=now(),updated_by='legacy-adoption-seed' where stable_key='legacy.roscardiovascular' and effective_revision is null;
